<template>
  <div class="remote-workbench">
    <p v-if="!agentId || !threadId" class="remote-notice">请先选择一个角色的对话，工作台将绑定该会话。</p>
    <p v-if="error" class="room-error">{{ error }}</p><p v-if="notice" class="remote-notice">{{ notice }}</p><p v-if="unresolved" class="room-error">上次操作结果待核对。<button @click="$emit('pending')">去核对</button></p>
    <nav class="file-workbench-tabs" aria-label="工作台视图"><button :aria-pressed="view === 'files'" :class="{ selected: view === 'files' }" :disabled="busy" @click="view = 'files'; run(loadTree)"><RemoteIcon name="folder" />会话文件</button><button :aria-pressed="view === 'terminal'" :class="{ selected: view === 'terminal' }" :disabled="busy" @click="view = 'terminal'; run(loadTerminals)"><RemoteIcon name="terminal" />远程终端</button></nav>
    <template v-if="view === 'files' && threadId">
      <section class="file-browser">
        <header class="file-browser-heading"><div><span class="file-browser-kicker">随手翻一翻</span><h2>工作区文件<span>{{ tree?.nodes?.length ?? '—' }} 项</span></h2></div><button class="file-browser-icon" :disabled="busy" aria-label="刷新目录" @click="run(loadTree)"><RemoteIcon name="refresh" :class="{ 'file-is-spinning': busy }" /></button></header>
        <RemoteFilePath :path="path" :disabled="busy" @navigate="go" />
        <div class="file-browser-tools"><label class="file-inline-search"><RemoteIcon name="search" /><input v-model="fileFilter" placeholder="在这个文件夹里找找…" aria-label="筛选当前目录" maxlength="200" /><button v-if="fileFilter" aria-label="清空筛选" @click="fileFilter = ''"><RemoteIcon name="close" /></button></label><button class="file-browser-icon" :disabled="busy" aria-label="搜索文件正文" title="搜索文件正文" @click="operation = 'search'; form = { query: '', isRegex: false, fileType: '' }"><RemoteIcon name="files" /></button></div>
        <RemoteFileState v-if="busy && !tree" title="正在整理文件夹…" loading />
        <RemoteFileState v-else-if="tree && !visibleNodes.length" :title="fileFilter ? '没有找到这个名字' : '这里还是空空的'" :description="fileFilter ? '换个关键词再找找吧' : '角色留在这个会话里的文件，会出现在这里'" :icon="fileFilter ? 'search' : 'folder'" />
        <div v-else class="file-browser-list" :aria-busy="busy"><article v-for="node in visibleNodes" :key="node.path" class="file-browser-row"><button class="file-row-main" :disabled="busy" :aria-label="`${node.type === 'directory' ? '打开文件夹' : '预览'} ${node.name}`" @click="node.type === 'directory' ? go(node.path) : previewFile(node)"><span v-if="node.type === 'directory'" class="file-folder-tile"><RemoteIcon name="folder" /></span><RemoteFileCover v-else :name="node.name" /><span class="file-row-copy"><strong>{{ node.name }}</strong><small>{{ node.type === 'directory' ? '文件夹' : fileHint(node) }}</small></span><RemoteIcon v-if="node.type === 'directory'" name="next" /></button><div class="file-row-actions"><button v-if="node.type !== 'directory' && canEdit(node.name)" class="file-browser-icon" :disabled="busy" :aria-label="`编辑文本 ${node.name}`" title="编辑文本" @click="openFile(node.path)"><RemoteIcon name="edit" /></button><button class="file-browser-icon" :disabled="busy" :aria-label="`管理 ${node.name}`" title="重命名或删除" @click="entry = node; operation = 'entry'; form = { newName: node.name }"><RemoteIcon name="more" /></button></div></article></div>
        <button v-if="filteredNodes.length > nodeLimit" class="file-load-more" @click="nodeLimit += 80">再展开一些<RemoteIcon name="down" /><small>{{ visibleNodes.length }} / {{ filteredNodes.length }}</small></button>
        <p class="file-browser-caption">点击文件预览 · 文本可单独编辑</p>
      </section>
      <div v-if="file" class="remote-manager-card"><h2>{{ file.path }}</h2><p v-if="file.truncated" class="remote-notice">文件超过当前编辑范围，只读显示，避免截断覆盖。</p><textarea v-model="content" class="remote-code-editor" :disabled="busy || file.truncated" spellcheck="false" aria-label="文件内容" /><div class="remote-manager-actions"><button :disabled="busy || hasChanges" @click="$emit('context', { ...scope(), workspaceContext: { filePath: file.path, fileHash: file.hash, fileDirty: false } })"><RemoteIcon name="chat" />引用到对话</button><button :disabled="busy || unresolved || file.truncated || content === original" @click="run(saveFile)"><RemoteIcon name="check" />保存文件</button><button :disabled="busy" @click="discard = 'reload'"><RemoteIcon name="refresh" />重新读取</button><button @click="discard = 'close'"><RemoteIcon name="close" />关闭文件</button></div></div>
      <section v-if="searchResult" class="remote-workspace-search-results"><h2><RemoteIcon name="search" />正文搜索 · {{ searchResult.total }} 处</h2><p v-if="searchResult.truncated" class="remote-help">结果已截断，可缩小关键词或目录范围。</p><article v-for="(match, index) in searchResult.matches || []" :key="index" class="remote-record-part"><strong>{{ match.file }}</strong><small>第 {{ match.line }} 行{{ match.column ? ' · 第 ' + match.column + ' 列' : '' }}</small><pre>{{ match.content }}</pre></article><p v-if="!searchResult.matches?.length" class="room-empty">没有匹配的正文</p></section>
    </template>
    <template v-if="view === 'terminal' && threadId">
      <p class="remote-help">命令在远程 infOS 执行节点运行。输出按游标读取，仅在此页可见时刷新。</p><div class="remote-manager-actions"><button :disabled="busy || unresolved" @click="operation = 'create'; form = { title: '', command: '', cwd: '', cols: 80, rows: 24 }"><RemoteIcon name="plus" />新终端</button><button :disabled="busy" @click="run(loadTerminals)"><RemoteIcon name="refresh" />刷新列表</button><button :disabled="busy || unresolved" @click="operation = 'cleanup'; form = { action: 'archive_completed' }"><RemoteIcon name="settings" />批量管理</button></div>
      <RemoteSelect :model-value="terminal?.id || ''" label="选择终端" :options="terminalOptions" :disabled="busy" @update:model-value="selectTerminal" />
      <template v-if="terminal"><pre ref="outputElement" class="remote-terminal-output" tabindex="0">{{ output || '等待输出…' }}</pre><p class="remote-help">{{ terminal.status }}<span v-if="terminal.exitCode != null"> · 退出码 {{ terminal.exitCode }}</span></p><form @submit.prevent="sendInput"><textarea v-model="terminalInput" class="remote-terminal-input" rows="2" aria-label="终端输入" placeholder="输入内容，点击发送后附加换行" /><button class="room-primary-button" :disabled="busy || unresolved"><RemoteIcon name="send" />发送输入</button></form><div class="remote-manager-actions"><button :disabled="busy || hasChanges" @click="$emit('context', { ...scope(), workspaceContext: { terminalId: terminal.id } })"><RemoteIcon name="chat" />引用终端到对话</button><button v-for="item in terminalActions" :key="item.id" :disabled="busy || unresolved" @click="operation = item.id; form = {}"><RemoteIcon :name="item.icon" />{{ item.label }}</button><button :disabled="busy || unresolved" @click="operation = 'resize'; form = { cols: 80, rows: 24 }"><RemoteIcon name="expand" />调整尺寸</button><button :disabled="busy || unresolved" @click="run(async () => { await write('terminals.pin', { id: terminal.id, body: { ...scope(), pinned: !terminal.pinned } }); await loadTerminals() })"><RemoteIcon name="tasks" />{{ terminal.pinned ? '取消固定' : '固定' }}</button></div></template>
    </template>
    <RoomDrawer v-if="discard" title="放弃未保存的文件改动？" @close="discard = null"><p>重新读取或关闭后，当前未保存的修改会丢失。</p><button class="room-primary-button" @click="discardFile">继续</button></RoomDrawer>
    <RoomDrawer v-if="operation" :title="operation === 'search' ? '搜索工作区' : operation === 'entry' ? '文件管理' : operation === 'delete' ? '删除文件或目录' : '终端操作'" :busy="busy" :before-close="beforeCloseOperation" @close="operation = null"><p v-if="error" class="room-error">{{ error }}</p><p v-if="operation === 'entry'">{{ entry.path }}</p><form @submit.prevent="submitOperation"><RemoteFields v-model="form" :fields="fields" :disabled="busy" /><p v-if="!['search', 'create', 'entry', 'delete'].includes(operation)" class="remote-notice">确认对远程终端执行此操作？</p><button class="room-primary-button" :disabled="busy || unresolved && operation !== 'search'">{{ operation === 'entry' ? '重命名' : '确认' }}</button></form><button v-if="operation === 'entry'" class="room-danger-button" :disabled="busy || unresolved" @click="operation = 'delete'; form = {}">删除此{{ entry.type === 'directory' ? '目录及其全部内容' : '文件' }}</button><p v-if="operation === 'delete'" class="room-error">将删除 {{ entry.path }}{{ entry.type === 'directory' ? ' 及其全部内容' : '' }}。</p></RoomDrawer>
    <RoomDrawer v-if="discardOperation" title="放弃未提交的输入？" @close="discardOperation = false"><p>此操作的表单还没有提交。</p><RemoteAction icon="close" tone="danger" @click="operation = null; discardOperation = false">放弃本次输入</RemoteAction></RoomDrawer>
  </div>
</template>
<script setup>
import { ref, computed, watch, onMounted, onBeforeUnmount, nextTick } from 'vue'
import { useRemoteManagement } from '../../composables/useRemoteManagement'
import { field, inferFields } from '../../services/remoteManagement'
import { readRemote, remoteState } from '../../stores/remote'
import RemoteIcon from './RemoteIcon.vue'
import RemoteFields from './RemoteFields.vue'
import RemoteAction from './RemoteAction.vue'
import RemoteSelect from './RemoteSelect.vue'
import RemoteFileCover from './RemoteFileCover.vue'
import RemoteFilePath from './RemoteFilePath.vue'
import RemoteFileState from './RemoteFileState.vue'
import { formatFileSize } from '../../services/remoteDocuments'
import '../../styles/remote-files.css'
import RoomDrawer from '../companion/RoomDrawer.vue'
const props = defineProps({ agentId: String, threadId: String })
const emit = defineEmits(['pending', 'resource', 'context'])
const { read, write, run, guard, busy, error, unresolved } = useRemoteManagement()
const view = ref('files'), path = ref('.'), tree = ref(null), file = ref(null), content = ref(''), original = ref(''), entry = ref(null), operation = ref(null), form = ref({}), notice = ref(''), discard = ref(null), searchResult = ref(null)
const terminals = ref(null), terminal = ref(null), terminalInput = ref(''), output = ref(''), outputElement = ref(null)
const fileFilter = ref(''), nodeLimit = ref(80)
const filteredNodes = computed(() => (tree.value?.nodes || []).filter(node => node.name.toLowerCase().includes(fileFilter.value.trim().toLowerCase())).sort((a, b) => Number(b.type === 'directory') - Number(a.type === 'directory') || a.name.localeCompare(b.name, 'zh-CN', { numeric: true })))
const visibleNodes = computed(() => filteredNodes.value.slice(0, nodeLimit.value))
watch([fileFilter, path], () => { nodeLimit.value = 80 })
function fileHint(node) { const size = node.sizeBytes ?? node.size; return `${node.name.includes('.') ? node.name.split('.').at(-1).toUpperCase().slice(0, 12) : '文件'}${typeof size === 'number' ? ` · ${formatFileSize(size)}` : ' · 点击预览'}` }
function canEdit(name) { return !/\.(pdf|docx?|xlsx?|pptx?|zip|7z|rar|gz|png|jpe?g|gif|webp|avif|bmp|ico|heic|mp[34]|m4[av]|wav|ogg|webm|mov|flac|woff2?|ttf|exe|dll|so|dylib)$/i.test(name) }
let cursor = 0, timer = null, reading = false, disposed = false, terminalGeneration = 0, pollFailed = false
const terminalActions = [{ id: 'interrupt', label: '中断', icon: 'stop' }, { id: 'kill', label: '终止', icon: 'alert' }, { id: 'archive', label: '归档', icon: 'folder' }, { id: 'close', label: '关闭', icon: 'close' }]
const terminalOptions = computed(() => [{ value: '', label: '选择终端' }, ...[...new Map([...(terminals.value?.terminals || []), ...(terminals.value?.history || [])].map(item => [item.id, item])).values()].map(item => ({ value: item.id, label: `${item.title || item.command || item.id} · ${item.status}` }))])
const fields = computed(() => operation.value === 'cleanup' ? [field('action', 'text', { choices: ['archive_completed', 'stop_agent', 'close_all'] })] : inferFields(form.value))
const operationBaseline = ref('{}'), discardOperation = ref(false)
watch(operation, () => { operationBaseline.value = JSON.stringify(form.value) })
const hasChanges = computed(() => !!file.value && content.value !== original.value || !!terminalInput.value.trim() || !!operation.value && JSON.stringify(form.value) !== operationBaseline.value)
function beforeCloseOperation() { if (JSON.stringify(form.value) !== operationBaseline.value) { discardOperation.value = true; return false }; return true }
defineExpose({ busy, hasChanges })
function scope() { if (!props.agentId || !props.threadId) throw new Error('请先选择对话'); return { agentId: props.agentId, threadId: props.threadId } }
async function loadTree() { tree.value = await read('workspace.tree', { params: { ...scope(), path: path.value } }) }
async function previewFile(node) { await run(async () => { const file = await readRemote({ kind: 'workspace_file', ...scope(), path: node.path }, { allowCached: false }); guard(); emit('resource', { kind: 'workspace', ...scope(), path: node.path, version: file.version, name: file.name || node.name }) }) }
async function go(target) { await run(async () => { const next = target === '..' ? path.value.split('/').slice(0, -1).join('/') || '.' : target; const data = await read('workspace.tree', { params: { ...scope(), path: next } }); path.value = next; tree.value = data; fileFilter.value = '' }) }
async function openFile(target) { await run(async () => { if (file.value && content.value !== original.value) throw new Error('请先保存或关闭当前文件'); const data = await read('workspace.read', { body: { ...scope(), path: target, offset: 0, limit: 128000 } }); if (typeof data?.content !== 'string' || typeof data.hash !== 'string') throw new Error('服务端文件响应不完整'); file.value = { ...data, path: target }; content.value = data.content; original.value = data.content }) }
async function saveFile() { if (!file.value || file.value.truncated) return; const data = await write('workspace.write', { body: { ...scope(), path: file.value.path, content: content.value, expectedHash: file.value.hash } }); guard(); file.value.hash = data.hash; original.value = content.value; notice.value = '文件已保存'; await loadTree() }
async function discardFile() { const action = discard.value, target = file.value?.path; discard.value = null; file.value = null; content.value = ''; original.value = ''; if (action === 'reload' && target) await openFile(target) }
async function loadTerminals() { pollFailed = false; terminals.value = await read('terminals.list', { params: scope() }); if (terminal.value) { const current = [...terminals.value.terminals, ...terminals.value.history].find(item => item.id === terminal.value.id); if (current) terminal.value = current; else { terminal.value = null; terminalGeneration++ } } }
function selectTerminal(id) { if (terminalInput.value.trim() && id !== terminal.value?.id) { error.value = '请先发送或清空当前终端输入，再切换终端'; return }; pollFailed = false; terminalGeneration++; terminal.value = [...(terminals.value?.terminals || []), ...(terminals.value?.history || [])].find(item => item.id === id) || null; output.value = ''; cursor = 0; error.value = ''; readOutput().catch(failure => { error.value = failure.message }) }
async function readOutput() { if (!terminal.value || reading || document.hidden || view.value !== 'terminal' || disposed || pollFailed || remoteState.connection !== 'online') return; const version = terminalGeneration, id = terminal.value.id; reading = true; try { const data = await read('terminals.read', { id, params: { ...scope(), cursor, limit: 16000 } }); if (version !== terminalGeneration) return; if (typeof data.output !== 'string' || !Number.isSafeInteger(data.nextCursor) || data.nextCursor < 0) throw new Error('终端输出格式无效，请刷新后再试'); const element = outputElement.value, atEnd = !element || element.scrollHeight - element.scrollTop - element.clientHeight < 48; if (data.droppedChars) output.value += '\n[较早的输出已由服务端释放]\n'; output.value = (output.value + String(data.output || '').replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, '').replace(/\x1b\][^\x07]*(?:\x07|\x1b\\)/g, '')).slice(-160000); cursor = data.nextCursor; terminal.value = { ...terminal.value, status: data.status, exitCode: data.exitCode }; if (atEnd) { await nextTick(); if (outputElement.value) outputElement.value.scrollTop = outputElement.value.scrollHeight } } finally { reading = false } }
async function sendInput() { await run(async () => { if (!terminal.value) return; await write('terminals.write', { id: terminal.value.id, body: { ...scope(), data: `${terminalInput.value}\n` } }); terminalInput.value = ''; await readOutput() }) }
async function submitOperation() { await run(async () => { const op = operation.value; if (op === 'search') searchResult.value = await read('workspace.search', { body: { ...scope(), ...form.value, path: path.value } }); else if (op === 'entry' || op === 'delete') { if (file.value && (file.value.path === entry.value.path || file.value.path.startsWith(`${entry.value.path}/`)) && content.value !== original.value) throw new Error('请先保存当前文件的修改'); await write(op === 'entry' ? 'workspace.rename' : 'workspace.delete', { body: { ...scope(), path: entry.value.path, ...(op === 'entry' ? { newName: form.value.newName } : {}) } }); if (file.value && (file.value.path === entry.value.path || file.value.path.startsWith(`${entry.value.path}/`))) file.value = null; await loadTree() } else if (op === 'create') { const body = { ...scope(), ...form.value }; for (const key of ['command', 'cwd', 'title']) if (!body[key]) delete body[key]; const value = await write('terminals.create', { body }); await loadTerminals(); selectTerminal(value.id) } else { await write(`terminals.${op}`, { id: op === 'cleanup' ? null : terminal.value?.id, body: { ...scope(), ...form.value } }); await loadTerminals() }; operation.value = null }) }
async function poll() { if (disposed) return; try { await readOutput() } catch (failure) { pollFailed = true; if (!disposed) error.value = failure.message } finally { if (!disposed) timer = setTimeout(poll, 1500) } }
onMounted(() => { if (props.threadId) run(loadTree); poll() })
onBeforeUnmount(() => { disposed = true; terminalGeneration++; clearTimeout(timer) })
</script>
